            'type': None,
            'username': None,
            'password': None

    def remove_cookies(self, names: Iterable[str]):
        """
        Removes cookies with the specified names from the session.

        Args:
            names (Iterable[str]): An iterable of cookie names to be removed.

        Example Usage:
            >>> from pathlib import Path
            >>> s = Session('session_data')
            >>> s['headers'] = {'User-Agent': 'HTTPie/1.0'}
            >>> s['cookies'] = {'session_id': 'abc123'}
            >>> print(s['headers'])  # Output: {'User-Agent': 'HTTPie/1.0'}
            >>> s.remove_cookies(['session_id'])
            >>> print(s['cookies'])  # Output: {}
        """
        for name in names:
            if name in self['cookies']:
                del self['cookies'][name]
