def repr_dict(d: dict) -> str:
    """
    Generates a string representation of a dictionary using the `pformat` function from the Python standard library.

    Parameters:
        d (dict): The dictionary to be represented as a string. This is expected to be a valid dictionary with key-value pairs where keys are strings and values can be any type that can be serialized into JSON format.

    Returns:
        str: A formatted string representation of the input dictionary, suitable for debugging or logging purposes.

    Example:
        >>> example_dict = {'key1': 'value1', 'key2': [1, 2, 3], 'key3': {'nestedKey': 'nestedValue'}}
        >>> print(repr_dict(example_dict))
        {
            'key1': 'value1',
            'key2': [
                1,
                2,
                3
            ],
            'key3': {
                'nestedKey': 'nestedValue'
            }
        }

    This function takes a dictionary as input and returns its string representation using the `pformat` function from Python’s standard library. The output is formatted to be more readable, especially useful for debugging or logging purposes when dealing with complex nested dictionaries.
    """
    return pformat(d)
