class MultiValueOrderedDict:
    'Multi-value dict for URL parameters and form data.'
    def items(self):
        """
        Generates key-value pairs from the dictionary-like object.

        This method iterates over the items of a dictionary-like object (assumed to have an `items` method similar to dictionaries) and yields each key-value pair. If a value is not a list, it converts it into a list before yielding.

        Yields:
            tuple: A tuple containing a key and its corresponding value.
        """
        for key, values in super().items():
            if not isinstance(values, list):
                values = [values]
            for value in values:
                yield key, value
